#!/usr/bin/env python3
import argparse,hashlib,json,statistics
from pathlib import Path
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--results',type=Path,required=True);ap.add_argument('--out',type=Path,required=True);a=ap.parse_args();search=json.loads((a.results/'search/rows.json').read_bytes());audit=json.loads((a.results/'audit_sheng.json').read_bytes());transfer=json.loads((a.results/'transfer_sheng.json').read_bytes());rows=[{k:v for k,v in r.items() if k!='records'} for r in transfer['rows']]
 summary=dict(tasks=len(rows),evaluations=audit['total_evaluations'],search_total_s=sum(r['elapsed_s'] for r in search),search_median_s=statistics.median(r['elapsed_s'] for r in search),search_range_s=[min(r['elapsed_s'] for r in search),max(r['elapsed_s'] for r in search)],initial_tasks_with_accepted_pose=audit['tasks_with_accepted_pose'],initial_tasks_with_tighter_upper=audit['tasks_with_tighter_upper'],initial_max_upper_improvement_us=audit['max_upper_improvement_us'],pooled_proposals=sum(len(v) for v in transfer['pools'].values()),transfer_tasks_with_tighter_upper=sum(r['nominal_pool_upper_us']<r['initial_search_upper_us'] for r in rows),nominal_cannot_cover_fixed_reserve=sum(r['nominal_cannot_cover_fixed_reserve'] for r in rows),actual_cannot_cover_fixed_reserve=sum(r['actual_cannot_cover_fixed_reserve'] for r in rows),best_nominal_rejected_by_actual=sum(not r['best_nominal_passes_actual'] for r in rows),nominal_gap_range_us=[min(r['nominal_gap_us'] for r in rows),max(r['nominal_gap_us'] for r in rows)],nominal_median_gap_us=statistics.median(r['nominal_gap_us'] for r in rows),tasks_with_nominal_gap_at_most_10000us=sum(r['nominal_gap_us']<=10000 for r in rows),initial_full_ray_pose_checks=audit['full_ray_pose_checks'],initial_full_ray_checks=audit['full_ray_checks'],initial_best_witness_checks=audit['best_witness_checks'],transfer_full_ray_pose_checks=transfer['full_ray_pose_checks'],transfer_full_ray_checks=transfer['full_ray_checks'],actual_pool_missing_witness=sum(r['best_actual_pool_index'] is None for r in rows))
 out=dict(summary=summary,rows=rows,source_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),scope='Offline receiver-only feasible search and post-search candidate transfer. Full raw data enters only the auditor on fixed candidates. Both upper bounds concern the frozen score/disc model; no physical collision, online net gain, optimizer completeness, true compression-loss measurement or fresh risk validation. Gap uses the existing4096-visit lower proof whose modeled online remainder was zero in every task.')
 a.out.write_text(json.dumps(out,indent=2)+'\n')
